INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1100, 'inconvenience', '/ˌɪnkənˈviːniəns/', 'noun, verb', '{"zh-TW":["不便；麻煩"],"en":["trouble or difficulty caused to someone"]}', NULL, 'cause/apologize for the inconvenience', '[{"en":"We apologize for any inconvenience caused.","zh-TW":"對造成的任何不便，我們深表歉意。"},{"en":"The construction work may inconvenience residents.","zh-TW":"施工可能會給居民帶來不便。"}]', '{"noun":"inconvenience","adjective":"inconvenient","verb":"inconvenience"}', NULL, 5, 1100),
(1101, 'incorporate', '/ɪnˈkɔːrpəreɪt/', 'verb', '{"zh-TW":["納入；合併","成立公司"],"en":["to include as part of something","to form a legal corporation"]}', NULL, 'incorporate feedback/changes/features', '[{"en":"We incorporated customer feedback into the new design.","zh-TW":"我們將客戶反饋納入新設計中。"},{"en":"The business was incorporated in 2020.","zh-TW":"這家企業於2020年註冊成立。"}]', '{"noun":"incorporation","verb":"incorporate","adjective":"incorporated"}', NULL, 4, 1101),
(1102, 'increase', '/ɪnˈkriːs/', 'verb, noun', '{"zh-TW":["增加；提高"],"en":["to become or make greater in amount"]}', NULL, 'increase in sales/demand / a significant increase', '[{"en":"Sales increased by 20% last quarter.","zh-TW":"上季度銷售額增長了20%。"},{"en":"There has been a steady increase in demand.","zh-TW":"需求持續穩定增長。"}]', '{"noun":"increase","verb":"increase","adjective":"increasing","adverb":"increasingly"}', NULL, 3, 1102),
(1103, 'incumbent', '/ɪnˈkʌmbənt/', 'adjective, noun', '{"zh-TW":["現任的；在職者","義不容辭的"],"en":["currently holding office; necessary as a duty","the current holder of a position"]}', NULL, 'incumbent president / incumbent upon', '[{"en":"It is incumbent upon management to ensure safety.","zh-TW":"管理層有義務確保安全。"},{"en":"The incumbent CEO has been in the role for five years.","zh-TW":"現任執行長已在職五年。"}]', '{"noun":"incumbent, incumbency","adjective":"incumbent"}', NULL, 3, 1103),
(1104, 'incur', '/ɪnˈkɜːr/', 'verb', '{"zh-TW":["招致；產生（費用、債務）"],"en":["to become subject to something unpleasant as a result of an action"]}', NULL, 'incur costs/expenses/debt/losses', '[{"en":"The company incurred significant losses last year.","zh-TW":"公司去年遭受了重大損失。"},{"en":"You may incur additional charges for late payment.","zh-TW":"逾期付款可能會產生額外費用。"}]', '{"noun":"incurrence","verb":"incur"}', NULL, 2, 1104),
(1105, 'index', '/ˈɪndeks/', 'noun, verb', '{"zh-TW":["指數；索引"],"en":["a system showing changes in value; an alphabetical list"]}', NULL, 'stock/price index / consumer price index', '[{"en":"The consumer price index rose by 3%.","zh-TW":"消費者物價指數上漲了3%。"},{"en":"Check the index at the back of the book.","zh-TW":"查看書後的索引。"}]', '{"noun":"index","verb":"index"}', NULL, 2, 1105),
(1106, 'indicate', '/ˈɪndɪkeɪt/', 'verb', '{"zh-TW":["指示；表明"],"en":["to point out or show"]}', NULL, 'indicate that / clearly indicate', '[{"en":"The survey indicates that customer satisfaction has improved.","zh-TW":"調查顯示客戶滿意度有所提高。"},{"en":"Red lights indicate danger.","zh-TW":"紅燈表示危險。"}]', '{"noun":"indication, indicator","verb":"indicate","adjective":"indicative"}', NULL, 3, 1106),
(1107, 'indict', '/ɪnˈdaɪt/', 'verb', '{"zh-TW":["起訴；控告"],"en":["to formally charge someone with a crime"]}', NULL, 'indict on charges / grand jury indictment', '[{"en":"He was indicted on fraud charges.","zh-TW":"他被以詐欺罪起訴。"},{"en":"The grand jury issued an indictment.","zh-TW":"大陪審團發出了起訴書。"}]', '{"noun":"indictment"}', NULL, 2, 1107),
(1108, 'indigenous', '/ɪnˈdɪdʒənəs/', 'adjective', '{"zh-TW":["本土的；原住民的"],"en":["originating in a particular place"]}', NULL, 'indigenous people/culture/species', '[{"en":"The project respects indigenous land rights.","zh-TW":"該項目尊重原住民的土地權利。"},{"en":"Indigenous plants are used in the garden design.","zh-TW":"花園設計中使用了本土植物。"}]', '{"noun":"indigenous","adjective":"indigenous"}', NULL, 4, 1108),
(1109, 'individual', '/ˌɪndɪˈvɪdʒuəl/', 'noun, adjective', '{"zh-TW":["個人","個別的；個人的"],"en":["a single person","relating to one person"]}', NULL, 'individual needs/differences/rights', '[{"en":"Each individual is responsible for their own work.","zh-TW":"每個人要對自己的工作負責。"},{"en":"We offer individual attention to every client.","zh-TW":"我們為每位客戶提供個別關注。"}]', '{"noun":"individual, individuality","adjective":"individual","adverb":"individually"}', NULL, 4, 1109),
(1110, 'induce', '/ɪnˈduːs/', 'verb', '{"zh-TW":["誘導；引起"],"en":["to persuade someone to do something; to cause"]}', NULL, 'induce changes/growth / induce someone to', '[{"en":"Nothing could induce him to change his mind.","zh-TW":"什麼都無法說服他改變主意。"},{"en":"The drug can induce drowsiness.","zh-TW":"這種藥物會引起嗜睡。"}]', '{"noun":"inducement, induction","verb":"induce"}', NULL, 2, 1110),
(1111, 'industrial', '/ɪnˈdʌstriəl/', 'adjective', '{"zh-TW":["工業的；產業的"],"en":["relating to industry or manufacturing"]}', NULL, 'industrial area/zone/production', '[{"en":"The factory is located in an industrial zone.","zh-TW":"工廠位於工業區。"},{"en":"Industrial production has declined this quarter.","zh-TW":"本季度工業生產有所下降。"}]', '{"noun":"industry, industrialization","adjective":"industrial","verb":"industrialize"}', NULL, 4, 1111),
(1112, 'industry', '/ˈɪndəstri/', 'noun', '{"zh-TW":["產業；工業","勤勉"],"en":["economic activity concerned with manufacturing","hard work"]}', NULL, 'the tourism/tech/finance industry', '[{"en":"The technology industry is growing rapidly.","zh-TW":"科技產業正在快速成長。"},{"en":"She is well-known in the fashion industry.","zh-TW":"她在時尚產業中很有名。"}]', '{"noun":"industry, industrialist","adjective":"industrial, industrious"}', NULL, 3, 1112),
(1113, 'inevitable', '/ɪnˈevɪtəbl/', 'adjective', '{"zh-TW":["不可避免的"],"en":["certain to happen; unavoidable"]}', '{"prefix":{"text":"in-","meaning":"not (不)"},"root":{"text":"evit","meaning":"avoid (避免)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"不能避免的。"}', 'inevitable result / inevitable change; inevitable consequence/result/outcome', '[{"en":"Change is inevitable in any organization.","zh-TW":"在任何組織中，變革都是不可避免的。"},{"en":"Delays were inevitable given the weather.","zh-TW":"考慮到天氣，延遲是不可避免的。"},{"en":"Change is inevitable in any organization.","zh-TW":"變革在任何組織中都是不可避免的。"},{"en":"It was inevitable that prices would rise.","zh-TW":"價格上漲是不可避免的。"}]', '{"adverb":"inevitably","noun":"inevitability","adjective":"inevitable"}', NULL, 4, 1113),
(1114, 'infer', '/ɪnˈfɜːr/', 'verb', '{"zh-TW":["推斷；推論"],"en":["to conclude from evidence and reasoning"]}', NULL, 'infer from / can be inferred', '[{"en":"We can infer from the data that sales are declining.","zh-TW":"我們可以從數據推斷出銷售額正在下降。"},{"en":"What can be inferred from this chart?","zh-TW":"從這張圖表中可以推斷出什麼？"}]', '{"noun":"inference","verb":"infer"}', NULL, 2, 1114),
(1115, 'inferior', '/ɪnˈfɪriər/', 'adjective', '{"zh-TW":["較差的；次等的"],"en":["lower in quality, status, or rank"]}', NULL, 'inferior quality/product / feel inferior', '[{"en":"The cheaper product is inferior in quality.","zh-TW":"較便宜的產品品質較差。"},{"en":"Customers complained about inferior materials.","zh-TW":"客戶抱怨材料品質低劣。"}]', '{"noun":"inferiority","adjective":"inferior"}', NULL, 3, 1115),
(1116, 'inflation', '/ɪnˈfleɪʃn/', 'noun', '{"zh-TW":["通貨膨脹"],"en":["a general increase in prices over time"]}', NULL, 'inflation rate / fight/curb inflation / rising inflation', '[{"en":"The inflation rate reached 8% this year.","zh-TW":"今年通貨膨脹率達到8%。"},{"en":"The central bank raised interest rates to combat inflation.","zh-TW":"央行提高利率以對抗通脹。"}]', '{"noun":"inflation","verb":"inflate","adjective":"inflationary"}', NULL, 3, 1116),
(1117, 'influence', '/ˈɪnfluəns/', 'noun', '{"zh-TW":["影響","影響；影響力"],"en":["the capacity to have an effect on someone or something","the power to affect someone or something"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"flu","meaning":"flow (流)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"流入其中產生作用，即「影響」。"}', 'have influence / under the influence of / positive influence; have influence on / under the influence of', '[{"en":"Social media has a huge influence on young people.","zh-TW":"社群媒體對年輕人有巨大的影響。"},{"en":"She used her influence to get the job.","zh-TW":"她利用自己的影響力得到了這份工作。"},{"en":"Social media has a huge influence on consumer behavior.","zh-TW":"社群媒體對消費者行為有巨大影響。"},{"en":"His research influenced the field significantly.","zh-TW":"他的研究對該領域產生了重大影響。"}]', '{"verb":"influence","adjective":"influential","noun":"influence"}', NULL, 3, 1117),
(1118, 'inform', '/ɪnˈfɔːrm/', 'verb', '{"zh-TW":["通知；告知"],"en":["to give someone facts or information"]}', NULL, 'inform someone of/about / keep informed', '[{"en":"Please inform us of any changes to your schedule.","zh-TW":"如果您的行程有變，請通知我們。"},{"en":"We will keep you informed of the progress.","zh-TW":"我們會隨時向您通報進展。"}]', '{"noun":"information","verb":"inform","adjective":"informative, informed"}', NULL, 2, 1118),
(1119, 'infrastructure', '/ˈɪnfrəstrʌktʃər/', 'noun', '{"zh-TW":["基礎設施"],"en":["the basic systems and services that a country needs to function"]}', NULL, 'transportation/IT infrastructure', '[{"en":"The government invested heavily in infrastructure.","zh-TW":"政府大力投資基礎設施。"},{"en":"Poor infrastructure hinders economic development.","zh-TW":"落後的基礎設施阻礙了經濟發展。"}]', '{"noun":"infrastructure"}', NULL, 5, 1119),
(1120, 'inherent', '/ɪnˈhɪrənt/', 'adjective', '{"zh-TW":["固有的；內在的"],"en":["existing as a natural or permanent quality"]}', NULL, 'inherent risk/problem/weakness', '[{"en":"There are inherent risks in any investment.","zh-TW":"任何投資都有固有的風險。"},{"en":"The plan has some inherent weaknesses.","zh-TW":"該計劃有一些固有的弱點。"}]', '{"adjective":"inherent","adverb":"inherently"}', NULL, 3, 1120),
(1121, 'inhibit', '/ɪnˈhɪbɪt/', 'verb', '{"zh-TW":["抑制；阻止"],"en":["to prevent or slow down a process"]}', NULL, 'inhibit growth/development/creativity', '[{"en":"Fear of failure can inhibit creativity.","zh-TW":"對失敗的恐懼會抑制創造力。"},{"en":"The drug inhibits the growth of cancer cells.","zh-TW":"這種藥物抑制癌細胞的生長。"}]', '{"noun":"inhibition, inhibitor","verb":"inhibit"}', NULL, 3, 1121),
(1122, 'initial', '/ɪˈnɪʃl/', 'adjective, noun', '{"zh-TW":["最初的；開始的","首字母"],"en":["existing at the beginning","the first letter of a name"]}', NULL, 'initial stage/phase/reaction', '[{"en":"The initial results are very promising.","zh-TW":"初步結果非常有前景。"},{"en":"Please write your initials on each page.","zh-TW":"請在每頁寫上您的姓名縮寫。"}]', '{"noun":"initial","adjective":"initial","adverb":"initially","verb":"initiate"}', NULL, 3, 1122),
(1123, 'initiate', '/ɪˈnɪʃieɪt/', 'verb', '{"zh-TW":["發起；開始"],"en":["to cause a process or action to begin"]}', NULL, 'initiate a project/discussion/process', '[{"en":"The manager initiated a review of company policies.","zh-TW":"經理發起了公司政策的審查。"},{"en":"Who initiated the negotiations?","zh-TW":"是誰發起了談判？"}]', '{"noun":"initiation, initiative, initiator","verb":"initiate","adjective":"initial"}', NULL, 3, 1123),
(1124, 'initiative', '/ɪˈnɪʃətɪv/', 'noun', '{"zh-TW":["主動性；倡議","主動性；倡議；計劃"],"en":["the ability to act independently","a new plan or program","the ability to act independently; a new plan to deal with a problem"]}', '{"prefix":{"text":"in-","meaning":"into (進入)"},"root":{"text":"it","meaning":"go (走)"},"suffix":{"text":"-iative","meaning":"relating to (相關的)"},"logic":"走進去開始行動的，即「主動性」。"}', 'take the initiative / new initiative / on one''s own initiative; take the initiative / a government initiative', '[{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這場活動。"},{"en":"The government launched a new environmental initiative.","zh-TW":"政府推出了新的環保倡議。"},{"en":"She took the initiative to organize the event.","zh-TW":"她主動組織了這次活動。"},{"en":"The company launched a new green initiative.","zh-TW":"公司發起了一項新的綠色倡議。"}]', '{"noun":"initiative, initiation","verb":"initiate"}', NULL, 4, 1124),
(1125, 'innovation', '/ˌɪnəˈveɪʃn/', 'noun', '{"zh-TW":["創新","創新；革新"],"en":["a new method, idea, or product"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"nov","meaning":"new (新)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"引入新事物的過程，即「創新」。"}', 'drive innovation / technological innovation; technological/product innovation / drive innovation', '[{"en":"Innovation is key to staying competitive.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"The company is known for its technological innovations.","zh-TW":"這家公司以技術創新聞名。"},{"en":"The company is known for its innovation in design.","zh-TW":"該公司以設計創新聞名。"}]', '{"verb":"innovate","adjective":"innovative","noun2":"innovator","noun":"innovation, innovator"}', NULL, 4, 1125),
(1126, 'innovative', '/ˈɪnəveɪtɪv/', 'adjective', '{"zh-TW":["創新的"],"en":["featuring new methods or ideas"]}', NULL, 'innovative approach/solution/technology', '[{"en":"The company is known for its innovative products.","zh-TW":"該公司以其創新產品聞名。"},{"en":"We need innovative solutions to complex problems.","zh-TW":"我們需要創新的解決方案來應對複雜問題。"}]', '{"noun":"innovation, innovator","adjective":"innovative","verb":"innovate"}', NULL, 4, 1126),
(1127, 'input', '/ˈɪnpʊt/', 'noun, verb', '{"zh-TW":["投入；輸入","提供意見"],"en":["what is put in; contribution","to enter data"]}', NULL, 'provide input / input data', '[{"en":"We value your input on this project.","zh-TW":"我們重視您對這個項目的意見。"},{"en":"Please input your password to continue.","zh-TW":"請輸入您的密碼以繼續。"}]', '{"noun":"input","verb":"input"}', NULL, 2, 1127),
(1128, 'inquire', '/ɪnˈkwaɪər/', 'verb', '{"zh-TW":["詢問；調查"],"en":["to ask for information"]}', NULL, 'inquire about / inquire into', '[{"en":"She called to inquire about the job opening.","zh-TW":"她打電話詢問職位空缺的事。"},{"en":"The committee will inquire into the matter.","zh-TW":"委員會將對此事進行調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 1128),
(1129, 'inquiry', '/ɪnˈkwaɪəri/', 'noun', '{"zh-TW":["詢問；調查"],"en":["a request for information; an official investigation"]}', NULL, 'make an inquiry / customer inquiry / public inquiry', '[{"en":"We received several inquiries about the new product.","zh-TW":"我們收到了幾份關於新產品的詢問。"},{"en":"A public inquiry was launched into the incident.","zh-TW":"對該事件展開了公開調查。"}]', '{"noun":"inquiry","verb":"inquire"}', NULL, 3, 1129),
(1130, 'insert', '/ɪnˈsɜːrt/', 'verb, noun', '{"zh-TW":["插入；嵌入","插入物"],"en":["to put something inside something else","something inserted"]}', NULL, 'insert a clause/coin/key', '[{"en":"Please insert your card into the machine.","zh-TW":"請將卡片插入機器。"},{"en":"A new clause was inserted into the contract.","zh-TW":"合同中插入了一項新條款。"}]', '{"noun":"insert, insertion","verb":"insert"}', NULL, 2, 1130),
(1131, 'inside', '/ɪnˈsaɪd/', 'preposition', '{"zh-TW":["在…裡面"],"en":["in or into the interior of"]}', NULL, 'inside information / inside out', '[{"en":"He has inside knowledge of the deal.","zh-TW":"他有這筆交易的內部消息。"},{"en":"She knows the business inside out.","zh-TW":"她對這個業務瞭若指掌。"}]', '{"preposition":"inside","noun":"inside","noun2":"insider","adjective":"inside"}', NULL, 2, 1131),
(1132, 'insight', '/ˈɪnsaɪt/', 'noun', '{"zh-TW":["洞察力；見解"],"en":["a deep understanding of something"]}', NULL, 'gain/provide insight into', '[{"en":"The report provides valuable insights into consumer behavior.","zh-TW":"該報告提供了關於消費者行為的寶貴見解。"},{"en":"She has keen insight into human nature.","zh-TW":"她對人性有敏銳的洞察力。"}]', '{"noun":"insight","adjective":"insightful"}', NULL, 3, 1132),
(1133, 'insist', '/ɪnˈsɪst/', 'verb', '{"zh-TW":["堅持；堅決要求"],"en":["to demand something firmly"]}', NULL, 'insist on / insist that', '[{"en":"The client insisted on a full refund.","zh-TW":"客戶堅持要求全額退款。"},{"en":"We insist that all safety protocols be followed.","zh-TW":"我們堅持必須遵守所有安全規程。"}]', '{"noun":"insistence","verb":"insist","adjective":"insistent"}', NULL, 2, 1133),
(1134, 'insolvency', '/ɪnˈsɒlvənsi/', 'noun', '{"zh-TW":["破產；無力償債"],"en":["the state of being unable to pay debts"]}', NULL, 'risk of insolvency / declare insolvency', '[{"en":"The firm is at risk of insolvency.","zh-TW":"該公司面臨破產風險。"},{"en":"They filed for insolvency last quarter.","zh-TW":"他們上一季申請了破產。"}]', '{"noun":"insolvency","adjective":"insolvent"}', NULL, 4, 1134),
(1135, 'inspect', '/ɪnˈspekt/', 'verb', '{"zh-TW":["檢查；視察"],"en":["to look at something closely to assess its condition","to look at something carefully to check its condition"]}', '{"prefix":{"text":"in-","meaning":"in (仔細)"},"root":{"text":"spect","meaning":"look (看)"},"logic":"仔細查看，即「檢查」。"}', 'inspect the premises / inspect for damage; inspect a building/facility/product', '[{"en":"Officials inspected the building for safety violations.","zh-TW":"官員檢查了建築物是否有安全違規。"},{"en":"The mechanic inspected the engine.","zh-TW":"技師檢查了引擎。"},{"en":"The building was inspected for safety violations.","zh-TW":"大樓接受了安全違規檢查。"},{"en":"Officials inspected the factory last week.","zh-TW":"官員上週視察了工廠。"}]', '{"noun":"inspection","noun2":"inspector","verb":"inspect"}', NULL, 3, 1135),
(1136, 'inspection', '/ɪnˈspekʃn/', 'noun', '{"zh-TW":["檢查；視察"],"en":["a careful examination of something"]}', NULL, 'safety/quality inspection / pass inspection', '[{"en":"The factory passed its annual safety inspection.","zh-TW":"工廠通過了年度安全檢查。"},{"en":"Regular inspections ensure product quality.","zh-TW":"定期檢查確保產品品質。"}]', '{"noun":"inspection, inspector","verb":"inspect"}', NULL, 4, 1136),
(1137, 'install', '/ɪnˈstɔːl/', 'verb', '{"zh-TW":["安裝；設置"],"en":["to put equipment or software in place for use"]}', NULL, 'install software/equipment/a system', '[{"en":"We need to install the new software by Friday.","zh-TW":"我們需要在週五前安裝新軟體。"},{"en":"Solar panels were installed on the roof.","zh-TW":"太陽能板被安裝在屋頂上。"}]', '{"noun":"installation, installment","verb":"install"}', NULL, 3, 1137),
(1138, 'installment', '/ɪnˈstɔːlmənt/', 'noun', '{"zh-TW":["分期付款"],"en":["one of several payments made over a period of time"]}', NULL, 'pay in installments / monthly installment', '[{"en":"You can pay for the equipment in monthly installments.","zh-TW":"你可以按月分期付款購買設備。"},{"en":"The first installment is due next week.","zh-TW":"第一期款項下週到期。"}]', '{"noun":"installment, installation","verb":"install"}', NULL, 4, 1138),
(1139, 'instance', '/ˈɪnstəns/', 'noun', '{"zh-TW":["實例；情況"],"en":["an example or case of something"]}', NULL, 'for instance / in this instance', '[{"en":"There have been several instances of fraud.","zh-TW":"已經發生了幾起詐騙事件。"},{"en":"For instance, many companies now allow remote work.","zh-TW":"例如，許多公司現在允許遠端工作。"}]', '{"noun":"instance"}', NULL, 3, 1139),
(1140, 'instead', '/ɪnˈstɛd/', 'adverb', '{"zh-TW":["代替；反而"],"en":["as an alternative"]}', NULL, 'instead of / use instead', '[{"en":"Let''s use email instead of fax.","zh-TW":"我們用電子郵件代替傳真吧。"},{"en":"Instead, we should focus on quality.","zh-TW":"相反地，我們應該著重品質。"}]', '{"adverb":"instead"}', NULL, 3, 1140),
(1141, 'institute', '/ˈɪnstɪtuːt/', 'noun, verb', '{"zh-TW":["機構；研究所","制定；開始"],"en":["an organization for education or research","to introduce or establish"]}', NULL, 'research institute / institute changes/reforms', '[{"en":"She works at a research institute.","zh-TW":"她在一家研究機構工作。"},{"en":"The company instituted new security measures.","zh-TW":"公司制定了新的安全措施。"}]', '{"noun":"institute, institution","verb":"institute","adjective":"institutional"}', NULL, 3, 1141),
(1142, 'institution', '/ˌɪnstɪˈtuːʃn/', 'noun', '{"zh-TW":["機構；制度"],"en":["a large organization; an established system"]}', NULL, 'financial/educational institution', '[{"en":"Banks are important financial institutions.","zh-TW":"銀行是重要的金融機構。"},{"en":"Marriage is a social institution.","zh-TW":"婚姻是一種社會制度。"}]', '{"noun":"institution","adjective":"institutional","verb":"institutionalize"}', NULL, 4, 1142),
(1143, 'instruction', '/ɪnˈstrʌkʃn/', 'noun', '{"zh-TW":["指示；說明；教學"],"en":["directions or orders; teaching"]}', NULL, 'follow instructions / give instructions', '[{"en":"Please read the instructions carefully before use.","zh-TW":"使用前請仔細閱讀說明。"},{"en":"He gave clear instructions to his team.","zh-TW":"他向團隊下達了明確的指示。"}]', '{"noun":"instruction, instructor","verb":"instruct","adjective":"instructive"}', NULL, 4, 1143),
(1144, 'instructor', '/ɪnˈstrʌktər/', 'noun', '{"zh-TW":["講師；教練"],"en":["a person who teaches"]}', NULL, 'driving instructor / fitness instructor', '[{"en":"The instructor explained the exercise.","zh-TW":"教練解釋了這個練習。"},{"en":"She works as a yoga instructor.","zh-TW":"她是一名瑜伽教練。"}]', '{"verb":"instruct","noun2":"instruction"}', NULL, 4, 1144),
(1145, 'instrument', '/ˈɪnstrəmənt/', 'noun', '{"zh-TW":["儀器；工具；樂器"],"en":["a tool or device; a means to achieve something"]}', NULL, 'financial instrument / measuring instrument', '[{"en":"The laboratory is equipped with precision instruments.","zh-TW":"實驗室配備了精密儀器。"},{"en":"Bonds are common financial instruments.","zh-TW":"債券是常見的金融工具。"}]', '{"noun":"instrument, instrumentation","adjective":"instrumental"}', NULL, 4, 1145),
(1146, 'insurance', '/ɪnˈʃʊrəns/', 'noun', '{"zh-TW":["保險"],"en":["an arrangement for compensation of loss or damage"]}', NULL, 'health/life/car insurance / insurance policy', '[{"en":"All employees receive health insurance benefits.","zh-TW":"所有員工都享有健康保險福利。"},{"en":"You should take out travel insurance.","zh-TW":"你應該購買旅行保險。"}]', '{"noun":"insurance, insurer","verb":"insure","adjective":"insured"}', NULL, 3, 1146),
(1147, 'integral', '/ˈɪntɪɡrəl/', 'adjective', '{"zh-TW":["不可或缺的；完整的"],"en":["essential; necessary for completeness"]}', NULL, 'integral part/component of', '[{"en":"Technology is an integral part of modern business.","zh-TW":"技術是現代商業不可或缺的一部分。"},{"en":"Teamwork is integral to our success.","zh-TW":"團隊合作對我們的成功至關重要。"}]', '{"noun":"integrity, integration","adjective":"integral","verb":"integrate"}', NULL, 3, 1147),
(1148, 'integrate', '/ˈɪntɪɡreɪt/', 'verb', '{"zh-TW":["整合；融合","整合；融入"],"en":["to combine into a whole","to combine things so they work together"]}', '{"prefix":{"text":"in-","meaning":"in (在內)"},"root":{"text":"tegr","meaning":"whole (完整)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使成為完整的一體，即「整合」。"}', 'integrate into / fully integrated; integrate into / integrate systems/data', '[{"en":"The new system integrates all departments.","zh-TW":"新系統整合了所有部門。"},{"en":"Immigrants gradually integrate into society.","zh-TW":"移民逐漸融入社會。"},{"en":"The new system integrates all departments into one platform.","zh-TW":"新系統將所有部門整合到一個平台上。"},{"en":"Immigrants often struggle to integrate into society.","zh-TW":"移民常常難以融入社會。"}]', '{"noun":"integration","adjective":"integrated","verb":"integrate"}', NULL, 3, 1148),
(1149, 'integrity', '/ɪnˈteɡrəti/', 'noun', '{"zh-TW":["正直；誠信","完整性"],"en":["the quality of being honest and morally upright","the state of being whole"]}', NULL, 'personal/professional integrity / data integrity', '[{"en":"He is known for his integrity and honesty.","zh-TW":"他以正直和誠實著稱。"},{"en":"We must ensure the integrity of the data.","zh-TW":"我們必須確保數據的完整性。"}]', '{"noun":"integrity","adjective":"integral"}', NULL, 3, 1149);
