(1150, 'intellectual', '/ˌɪntəˈlektʃuəl/', 'adjective, noun', '{"zh-TW":["智力的；知識分子"],"en":["relating to the intellect; a person of high intelligence"]}', NULL, 'intellectual property / intellectual capital', '[{"en":"Intellectual property rights must be protected.","zh-TW":"知識產權必須受到保護。"},{"en":"The company invests heavily in intellectual capital.","zh-TW":"公司大力投資智力資本。"}]', '{"noun":"intellect, intellectual, intelligence","adjective":"intellectual","adverb":"intellectually"}', NULL, 4, 1150),
(1151, 'intelligence', '/ɪnˈtelɪdʒəns/', 'noun', '{"zh-TW":["智力；情報"],"en":["the ability to learn; secret information"]}', NULL, 'artificial intelligence / business intelligence / market intelligence', '[{"en":"Artificial intelligence is transforming many industries.","zh-TW":"人工智慧正在改變許多行業。"},{"en":"Business intelligence tools help analyze data.","zh-TW":"商業智慧工具有助於分析數據。"}]', '{"noun":"intelligence","adjective":"intelligent","adverb":"intelligently"}', NULL, 4, 1151),
(1152, 'intend', '/ɪnˈtend/', 'verb', '{"zh-TW":["打算；意圖"],"en":["to plan or mean to do something"]}', NULL, 'intend to do / be intended for', '[{"en":"We intend to expand our operations next year.","zh-TW":"我們打算明年擴大營運。"},{"en":"This product is intended for professional use.","zh-TW":"此產品專供專業使用。"}]', '{"noun":"intention, intent","verb":"intend","adjective":"intentional, intended","adverb":"intentionally"}', NULL, 2, 1152),
(1153, 'intense', '/ɪnˈtens/', 'adjective', '{"zh-TW":["強烈的；劇烈的"],"en":["very great or extreme in degree"]}', NULL, 'intense competition/pressure/heat', '[{"en":"The competition in this market is intense.","zh-TW":"這個市場的競爭非常激烈。"},{"en":"She felt intense pressure to meet the deadline.","zh-TW":"她感受到巨大的壓力要趕上截止日期。"}]', '{"noun":"intensity","adjective":"intense, intensive","verb":"intensify","adverb":"intensely"}', NULL, 3, 1153),
(1154, 'interact', '/ˌɪntərˈækt/', 'verb', '{"zh-TW":["互動；交流"],"en":["to communicate or work with others"]}', NULL, 'interact with customers/colleagues', '[{"en":"Employees interact with customers on a daily basis.","zh-TW":"員工每天都與客戶互動。"},{"en":"The software allows users to interact with the data.","zh-TW":"該軟體允許用戶與數據互動。"}]', '{"noun":"interaction","verb":"interact","adjective":"interactive"}', NULL, 3, 1154),
(1155, 'interest', '/ˈɪntrəst/', 'noun, verb', '{"zh-TW":["興趣；利息；利益"],"en":["curiosity; money paid for borrowing; advantage"]}', NULL, 'interest rate / in the interest of / of interest', '[{"en":"The interest rate was raised to 5%.","zh-TW":"利率被提高到5%。"},{"en":"This topic is of great interest to investors.","zh-TW":"這個話題對投資者非常感興趣。"}]', '{"noun":"interest","verb":"interest","adjective":"interesting, interested"}', NULL, 3, 1155),
(1156, 'interface', '/ˈɪntərfeɪs/', 'noun', '{"zh-TW":["介面"],"en":["the way a user interacts with a computer"]}', NULL, 'user interface / graphical interface', '[{"en":"The interface is easy to use.","zh-TW":"介面很容易使用。"},{"en":"We redesigned the user interface.","zh-TW":"我們重新設計了使用者介面。"}]', NULL, NULL, 3, 1156),
(1157, 'interfere', '/ˌɪntərˈfɪr/', 'verb', '{"zh-TW":["干涉；妨礙"],"en":["to get involved in something without being asked; to prevent"]}', NULL, 'interfere with / interfere in', '[{"en":"Please do not interfere with the investigation.","zh-TW":"請不要干涉調查。"},{"en":"Noise can interfere with concentration.","zh-TW":"噪音會妨礙注意力集中。"}]', '{"noun":"interference","verb":"interfere"}', NULL, 3, 1157),
(1158, 'interim', '/ˈɪntərɪm/', 'adjective, noun', '{"zh-TW":["臨時的；過渡期的"],"en":["temporary; for the time being"]}', NULL, 'interim report/measure/CEO / in the interim', '[{"en":"An interim manager was appointed during the transition.","zh-TW":"過渡期間任命了一位臨時經理。"},{"en":"In the interim, please continue with current procedures.","zh-TW":"在此期間，請繼續按照現有程序執行。"}]', '{"noun":"interim","adjective":"interim"}', NULL, 3, 1158),
