(1162, 'interpret', '/ɪnˈtɜːrprɪt/', 'verb', '{"zh-TW":["解釋；口譯"],"en":["to explain the meaning of; to translate orally"]}', NULL, 'interpret data/results / interpret for someone', '[{"en":"The data can be interpreted in different ways.","zh-TW":"數據可以有不同的解讀方式。"},{"en":"She interpreted for the foreign delegates.","zh-TW":"她為外國代表做口譯。"}]', '{"noun":"interpretation, interpreter","verb":"interpret"}', NULL, 3, 1162),
(1163, 'intersection', '/ˌɪntərˈsekʃn/', 'noun', '{"zh-TW":["交叉口；交集"],"en":["the point where two things cross; a shared area"]}', NULL, 'at the intersection of / road intersection', '[{"en":"Our product sits at the intersection of technology and design.","zh-TW":"我們的產品位於技術和設計的交集處。"},{"en":"Turn left at the next intersection.","zh-TW":"在下一個路口左轉。"}]', '{"noun":"intersection","verb":"intersect"}', NULL, 4, 1163),
