(1165, 'interview', '/ˈɪntərvjuː/', 'noun, verb', '{"zh-TW":["面試；訪談","面試；採訪"],"en":["a formal meeting for assessment; a conversation for media","to conduct an interview"]}', NULL, 'job interview / conduct an interview', '[{"en":"She has a job interview tomorrow morning.","zh-TW":"她明天早上有一場工作面試。"},{"en":"The journalist interviewed the CEO.","zh-TW":"記者採訪了執行長。"}]', '{"noun":"interview, interviewer, interviewee","verb":"interview"}', NULL, 3, 1165),
