(1168, 'invaluable', '/ɪnˈvæljuəbl/', 'adjective', '{"zh-TW":["無價的；極有價值的"],"en":["extremely useful; priceless"]}', NULL, 'invaluable experience/resource/asset', '[{"en":"Her expertise has been invaluable to the project.","zh-TW":"她的專業知識對項目極有價值。"},{"en":"The internship provided invaluable work experience.","zh-TW":"實習提供了寶貴的工作經驗。"}]', '{"adjective":"invaluable, valuable"}', NULL, 4, 1168),
