(1170, 'invest', '/ɪnˈvest/', 'verb', '{"zh-TW":["投資"],"en":["to put money into something for profit","to put money into something to make a profit"]}', '{"prefix":{"text":"in-","meaning":"in (進入)"},"root":{"text":"vest","meaning":"clothe/cover (覆蓋)"},"logic":"把資金包進某事物中，即「投資」。"}', 'invest in / invest time / invest money; invest in stocks/real estate / invest time', '[{"en":"She invested her savings in stocks.","zh-TW":"她把積蓄投資在股票上。"},{"en":"The company invested heavily in research.","zh-TW":"公司在研究方面投入了大量資金。"},{"en":"She invested heavily in technology stocks.","zh-TW":"她大量投資科技股。"},{"en":"The company plans to invest in new equipment.","zh-TW":"公司計劃投資新設備。"}]', '{"noun":"investment","noun2":"investor","verb":"invest"}', NULL, 2, 1170),
(1171, 'investigate', '/ɪnˈvestɪɡeɪt/', 'verb', '{"zh-TW":["調查；研究"],"en":["to carry out a systematic examination"]}', NULL, 'investigate a case/claim/complaint', '[{"en":"Police are investigating the cause of the fire.","zh-TW":"警方正在調查火災原因。"},{"en":"The committee will investigate the allegations.","zh-TW":"委員會將調查這些指控。"}]', '{"noun":"investigation, investigator","verb":"investigate","adjective":"investigative"}', NULL, 4, 1171),
