(1175, 'isolate', '/ˈaɪsəleɪt/', 'verb', '{"zh-TW":["隔離；孤立"],"en":["to separate from others"]}', NULL, 'isolate a problem/variable / socially isolated', '[{"en":"Scientists isolated the virus in the laboratory.","zh-TW":"科學家在實驗室中分離了病毒。"},{"en":"The town was isolated by the flood.","zh-TW":"小鎮因洪水而被孤立。"}]', '{"noun":"isolation","verb":"isolate","adjective":"isolated"}', NULL, 3, 1175),
(1176, 'issue', '/ˈɪʃuː/', 'noun, verb', '{"zh-TW":["議題；問題","發行；發布"],"en":["a topic for discussion; a problem","to officially provide or publish"]}', NULL, 'address an issue / issue a statement/warning', '[{"en":"We need to address this issue immediately.","zh-TW":"我們需要立即解決這個問題。"},{"en":"The company issued a press release.","zh-TW":"公司發布了一份新聞稿。"}]', '{"noun":"issue","verb":"issue"}', NULL, 2, 1176),
