(1181, 'jeopardize', '/ˈdʒepərdaɪz/', 'verb', '{"zh-TW":["危及；損害"],"en":["to put something in danger of being harmed or lost"]}', NULL, 'jeopardize safety/chances/career', '[{"en":"His reckless behavior could jeopardize the entire project.","zh-TW":"他魯莽的行為可能危及整個項目。"},{"en":"Don''t jeopardize your career over a minor disagreement.","zh-TW":"不要因為小分歧而危及你的職業生涯。"}]', '{"noun":"jeopardy","verb":"jeopardize"}', NULL, 4, 1181),
