(1184, 'joint', '/dʒɔɪnt/', 'adjective, noun', '{"zh-TW":["共同的；聯合的","關節；接合處"],"en":["shared by two or more parties","a point of connection"]}', NULL, 'joint venture / joint effort / joint account', '[{"en":"The two companies formed a joint venture.","zh-TW":"兩家公司成立了一家合資企業。"},{"en":"This was a joint effort between departments.","zh-TW":"這是各部門的共同努力。"}]', '{"noun":"joint","adjective":"joint","adverb":"jointly"}', NULL, 2, 1184),
(1185, 'journal', '/ˈdʒɜːrnl/', 'noun', '{"zh-TW":["期刊；日誌"],"en":["a scholarly publication; a daily record"]}', NULL, 'academic journal / keep a journal', '[{"en":"The research was published in a leading journal.","zh-TW":"該研究發表在一份頂尖期刊上。"},{"en":"She keeps a journal of her daily activities.","zh-TW":"她記錄每天活動的日誌。"}]', '{"noun":"journal, journalism, journalist"}', NULL, 3, 1185),
(1186, 'judge', '/dʒʌdʒ/', 'noun', '{"zh-TW":["法官；裁判","判斷；評價"],"en":["a person who decides cases in court","to form an opinion about"]}', NULL, 'judge a case / pass judgment; judge by/from / pass judgment', '[{"en":"The judge sentenced him to five years.","zh-TW":"法官判他五年。"},{"en":"Don''t judge people by appearances.","zh-TW":"不要以貌取人。"},{"en":"Don''t judge a book by its cover.","zh-TW":"不要以貌取人。"},{"en":"The judge ruled in favor of the plaintiff.","zh-TW":"法官判原告勝訴。"}]', '{"verb":"judge","noun2":"judgment","noun":"judge, judgment","adjective":"judgmental"}', NULL, 2, 1186),
(1187, 'judgment', '/ˈdʒʌdʒmənt/', 'noun', '{"zh-TW":["判斷力；判決"],"en":["the ability to make sensible decisions; a court decision"]}', NULL, 'good/poor judgment / exercise judgment', '[{"en":"She showed good judgment in handling the situation.","zh-TW":"她在處理情況時表現出良好的判斷力。"},{"en":"The court will deliver its judgment next week.","zh-TW":"法院將在下週做出判決。"}]', '{"noun":"judgment, judge","verb":"judge","adjective":"judgmental"}', NULL, 3, 1187),
(1188, 'jump', '/dʒʌmp/', 'verb', '{"zh-TW":["跳躍；暴漲"],"en":["to push oneself into the air","to increase suddenly"]}', NULL, 'jump start / price jump', '[{"en":"Stock prices jumped 10% today.","zh-TW":"股價今天暴漲了10%。"},{"en":"We need to jump-start the project.","zh-TW":"我們需要快速啟動這個專案。"}]', '{"verb":"jump","noun":"jump"}', NULL, 1, 1188),
(1189, 'jurisdiction', '/ˌdʒʊrɪsˈdɪkʃn/', 'noun', '{"zh-TW":["管轄權；司法權"],"en":["the official power to make legal decisions"]}', NULL, 'fall under/within jurisdiction', '[{"en":"This case falls outside our jurisdiction.","zh-TW":"這個案件不在我們的管轄範圍內。"},{"en":"The dispute was settled by the local jurisdiction.","zh-TW":"爭議由當地司法機關解決。"}]', '{"noun":"jurisdiction","adjective":"jurisdictional"}', NULL, 4, 1189),
(1190, 'jury', '/ˈdʒʊri/', 'noun', '{"zh-TW":["陪審團"],"en":["a group of people who decide if someone is guilty"]}', NULL, 'jury duty / jury trial', '[{"en":"The jury found him guilty.","zh-TW":"陪審團裁定他有罪。"},{"en":"She was called for jury duty.","zh-TW":"她被叫去擔任陪審員。"}]', '{"noun2":"juror"}', NULL, 1, 1190),
(1191, 'justice', '/ˈdʒʌstɪs/', 'noun', '{"zh-TW":["正義；司法"],"en":["fairness; the legal system"]}', NULL, 'justice system / bring to justice', '[{"en":"They demand justice for the victims.","zh-TW":"他們要求為受害者伸張正義。"},{"en":"The criminal was brought to justice.","zh-TW":"罪犯被繩之以法。"}]', NULL, NULL, 3, 1191),
(1192, 'justify', '/ˈdʒʌstɪfaɪ/', 'verb', '{"zh-TW":["證明...合理；為...辯護"],"en":["to show that something is reasonable or right"]}', NULL, 'justify a decision/expense/action', '[{"en":"How can you justify such a large expense?","zh-TW":"你怎麼能證明這麼大的開支是合理的？"},{"en":"The results justify our investment.","zh-TW":"結果證明我們的投資是合理的。"}]', '{"noun":"justification","verb":"justify","adjective":"justifiable, justified"}', NULL, 3, 1192),
(1193, 'keen', '/kiːn/', 'adjective', '{"zh-TW":["熱衷的；敏銳的"],"en":["eager or enthusiastic; sharp or acute"]}', NULL, 'keen interest / keen on / keen sense', '[{"en":"She is keen on learning new languages.","zh-TW":"她熱衷於學習新語言。"},{"en":"He has a keen eye for detail.","zh-TW":"他對細節有敏銳的眼光。"}]', '{"noun":"keenness","adjective":"keen","adverb":"keenly"}', NULL, 1, 1193),
(1194, 'keep', '/kiːp/', 'verb', '{"zh-TW":["保持；持續"],"en":["to continue to have","to remain in a state"]}', NULL, 'keep up / keep in mind', '[{"en":"Keep in mind the deadline is Friday.","zh-TW":"請記住截止日期是週五。"},{"en":"Keep up the good work.","zh-TW":"繼續保持好的表現。"}]', '{"verb":"keep","noun":"keeper"}', NULL, 1, 1194),
(1195, 'key', '/kiː/', 'noun, adjective', '{"zh-TW":["鑰匙；關鍵","關鍵的"],"en":["a small metal instrument for opening locks; essential","of crucial importance"]}', NULL, 'key factor/role/issue / the key to success', '[{"en":"Communication is the key to a successful partnership.","zh-TW":"溝通是成功合作的關鍵。"},{"en":"She plays a key role in the organization.","zh-TW":"她在組織中扮演著關鍵角色。"}]', '{"noun":"key","adjective":"key"}', NULL, 1, 1195),
(1196, 'keynote', '/ˈkiːnoʊt/', 'noun, adjective', '{"zh-TW":["主旨；基調"],"en":["the main theme or most important point; a principal speech"]}', NULL, 'keynote speech/speaker/address', '[{"en":"The CEO delivered the keynote speech at the conference.","zh-TW":"執行長在會議上發表了主題演講。"},{"en":"Innovation was the keynote of the event.","zh-TW":"創新是這次活動的主旨。"}]', '{"noun":"keynote"}', NULL, 3, 1196),
(1197, 'kick', '/kɪk/', 'verb', '{"zh-TW":["踢；啟動"],"en":["to strike with the foot","to start something"]}', NULL, 'kick off / kick start', '[{"en":"Let''s kick off the meeting.","zh-TW":"讓我們開始會議吧。"},{"en":"The campaign kicks off next Monday.","zh-TW":"活動下週一開始。"}]', '{"verb":"kick","noun":"kick","noun2":"kickoff"}', NULL, 1, 1197),
(1198, 'kill', '/kɪl/', 'verb', '{"zh-TW":["殺死；終止"],"en":["to cause death","to end something"]}', NULL, 'kill time / overkill', '[{"en":"They decided to kill the project.","zh-TW":"他們決定終止這個專案。"},{"en":"That level of detail is overkill.","zh-TW":"那種程度的細節太過頭了。"}]', '{"verb":"kill","noun":"killer","noun2":"killing"}', NULL, 1, 1198),
(1199, 'kind', '/kaɪnd/', 'noun', '{"zh-TW":["種類；善良的"],"en":["a type or category","friendly and generous"]}', NULL, 'kind of / all kinds of', '[{"en":"What kind of work do you do?","zh-TW":"你做什麼類型的工作？"},{"en":"She is very kind to new employees.","zh-TW":"她對新員工很友善。"}]', '{"noun":"kind","adjective":"kind","noun2":"kindness","adverb":"kindly"}', NULL, 1, 1199);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(1200, 'kindergarten', '/ˈkɪndərɡɑːrtən/', 'noun', '{"zh-TW":["幼稚園"],"en":["a school for young children aged 4-6"]}', NULL, 'kindergarten teacher / start kindergarten', '[{"en":"My son starts kindergarten next year.","zh-TW":"我兒子明年開始上幼稚園。"},{"en":"She teaches kindergarten.","zh-TW":"她教幼稚園。"}]', NULL, NULL, 4, 1200),
(1201, 'king', '/kɪŋ/', 'noun', '{"zh-TW":["國王；巨頭"],"en":["a male ruler","the most important person"]}', NULL, 'content is king / king of the market', '[{"en":"In digital marketing, content is king.","zh-TW":"在數位行銷中，內容為王。"},{"en":"They are the king of the electronics market.","zh-TW":"他們是電子產品市場的霸主。"}]', '{"noun":"king","noun2":"kingdom"}', NULL, 1, 1201),
(1202, 'kitchen', '/ˈkɪtʃɪn/', 'noun', '{"zh-TW":["廚房"],"en":["a room where food is prepared"]}', NULL, 'office kitchen / kitchen staff', '[{"en":"The office kitchen is on the second floor.","zh-TW":"辦公室廚房在二樓。"},{"en":"Kitchen staff must wear gloves.","zh-TW":"廚房人員必須戴手套。"}]', '{"noun":"kitchen"}', NULL, 3, 1202),
(1203, 'knee', '/niː/', 'noun', '{"zh-TW":["膝蓋"],"en":["the joint in the middle of the leg"]}', NULL, 'knee-jerk reaction / bring to its knees', '[{"en":"Don''t make knee-jerk decisions.","zh-TW":"不要做出衝動的決定。"},{"en":"The recession brought the industry to its knees.","zh-TW":"經濟衰退重創了這個產業。"}]', '{"noun":"knee"}', NULL, 1, 1203),
(1204, 'knife', '/naɪf/', 'noun', '{"zh-TW":["刀"],"en":["a tool with a sharp blade for cutting"]}', NULL, 'knife edge / under the knife', '[{"en":"The decision is on a knife edge.","zh-TW":"這個決定懸而未決。"},{"en":"Budgets are always under the knife.","zh-TW":"預算總是面臨削減。"}]', '{"noun":"knife","plural":"knives"}', NULL, 2, 1204),
(1205, 'knock', '/nɒk/', 'verb', '{"zh-TW":["敲；敲打"],"en":["to hit a surface to attract attention"]}', NULL, 'knock on the door / knock down', '[{"en":"Opportunity doesn''t knock twice.","zh-TW":"機會不會敲兩次門。"},{"en":"They knocked down the old warehouse.","zh-TW":"他們拆除了舊倉庫。"}]', '{"verb":"knock","noun":"knock","noun2":"knockout"}', NULL, 2, 1205),
(1206, 'know', '/noʊ/', 'verb', '{"zh-TW":["知道；認識"],"en":["to be aware of","to be familiar with"]}', NULL, 'know-how / as far as I know', '[{"en":"We have the technical know-how.","zh-TW":"我們有技術專業知識。"},{"en":"As far as I know, the deal is still on.","zh-TW":"據我所知，交易還在進行中。"}]', '{"verb":"know","noun":"knowledge","adjective":"known","noun2":"know-how"}', NULL, 1, 1206),
(1207, 'knowledge', '/ˈnɑːlɪdʒ/', 'noun', '{"zh-TW":["知識；了解"],"en":["facts, information, and skills acquired through experience or education"]}', NULL, 'to my knowledge / common knowledge / knowledge of', '[{"en":"A good knowledge of English is essential for this job.","zh-TW":"良好的英語知識對這份工作至關重要。"},{"en":"To my knowledge, no one has complained.","zh-TW":"據我所知，沒有人抱怨。"}]', '{"noun":"knowledge","adjective":"knowledgeable"}', NULL, 3, 1207),
(1208, 'label', '/ˈleɪbl/', 'noun', '{"zh-TW":["標籤","貼標籤；稱呼"],"en":["a piece of paper attached to an object giving information about it","a piece of paper giving information about something","to attach a label to; to categorize"]}', '{"root":{"text":"label","meaning":"strip/ribbon (帶子)"},"logic":"源自古法語，指貼在物品上的資訊帶。"}', 'price label / brand label; product label / label as', '[{"en":"Check the label for washing instructions.","zh-TW":"查看標籤上的洗滌說明。"},{"en":"The label shows the country of origin.","zh-TW":"標籤顯示原產地。"},{"en":"Check the label for the ingredients list.","zh-TW":"查看標籤上的成分表。"},{"en":"The product was labeled as organic.","zh-TW":"該產品被標註為有機產品。"}]', '{"verb":"label","noun":"label"}', NULL, 2, 1208),
(1209, 'labor', '/ˈleɪbər/', 'noun', '{"zh-TW":["勞動；勞工"],"en":["physical or mental work; workers as a group"]}', NULL, 'labor market / labor force / labor costs', '[{"en":"The company is trying to reduce labor costs.","zh-TW":"公司正在努力降低勞動成本。"},{"en":"There is a shortage in the labor market.","zh-TW":"勞動市場存在短缺。"}]', '{"noun":"labor, laborer","verb":"labor","adjective":"laborious"}', NULL, 2, 1209),
(1210, 'lack', '/læk/', 'noun', '{"zh-TW":["缺乏","缺乏；不足"],"en":["the state of being without something","the state of not having something"]}', '{"root":{"text":"lack","meaning":"want/deficiency (缺乏)"},"logic":"指不足或缺少某物的狀態。"}', 'lack of / for lack of / lack confidence; lack of experience/funding/resources', '[{"en":"The project failed due to lack of funding.","zh-TW":"專案因缺乏資金而失敗。"},{"en":"He lacks the experience for this role.","zh-TW":"他缺乏擔任這個角色的經驗。"},{"en":"The project failed due to a lack of funding.","zh-TW":"該項目因缺乏資金而失敗。"},{"en":"He lacks the experience needed for this role.","zh-TW":"他缺乏這個職位所需的經驗。"}]', '{"verb":"lack","adjective":"lacking","noun":"lack"}', NULL, 1, 1210),
(1211, 'lady', '/ˈleɪdi/', 'noun', '{"zh-TW":["女士"],"en":["a polite word for a woman"]}', NULL, 'ladies and gentlemen / leading lady', '[{"en":"Ladies and gentlemen, welcome to the conference.","zh-TW":"各位女士先生，歡迎來到會議。"},{"en":"She is the leading lady of the industry.","zh-TW":"她是這個產業的領軍人物。"}]', '{"noun":"lady"}', NULL, 1, 1211),
(1212, 'lag', '/læɡ/', 'noun, verb', '{"zh-TW":["落後；延遲"],"en":["a delay or period of time between two events"]}', NULL, 'time lag / jet lag / lag behind', '[{"en":"There is often a lag between policy changes and results.","zh-TW":"政策變更和結果之間通常有時間差。"},{"en":"Our sales figures lag behind the competition.","zh-TW":"我們的銷售數字落後於競爭對手。"}]', '{"noun":"lag","verb":"lag"}', NULL, 1, 1212),
(1213, 'lake', '/leɪk/', 'noun', '{"zh-TW":["湖"],"en":["a large body of water surrounded by land"]}', NULL, 'lakeside / by the lake', '[{"en":"The resort is by the lake.","zh-TW":"度假村在湖邊。"},{"en":"The team-building event is at the lakeside.","zh-TW":"團建活動在湖畔舉行。"}]', '{"noun":"lake","noun2":"lakeside"}', NULL, 1, 1213),
(1214, 'land', '/lænd/', 'noun', '{"zh-TW":["土地；著陸"],"en":["an area of ground","to arrive on the ground"]}', NULL, 'land a deal / on land', '[{"en":"We landed a major contract.","zh-TW":"我們拿下了一個大合約。"},{"en":"They purchased land for the new office.","zh-TW":"他們為新辦公室購買了土地。"}]', '{"noun":"land","verb":"land","noun2":"landing","noun3":"landlord"}', NULL, 1, 1214),
(1215, 'landlord', '/ˈlændlɔːrd/', 'noun', '{"zh-TW":["房東"],"en":["a person who rents land or property to others"]}', NULL, 'notify the landlord / landlord and tenant', '[{"en":"The landlord increased the rent by 10%.","zh-TW":"房東將租金提高了10%。"},{"en":"Please notify the landlord before moving out.","zh-TW":"搬出前請通知房東。"}]', '{"noun":"landlord, landlady"}', NULL, 3, 1215),
(1216, 'landmark', '/ˈlændmɑːrk/', 'noun, adjective', '{"zh-TW":["地標；里程碑"],"en":["an easily recognized feature; a significant event"]}', NULL, 'landmark decision/ruling/agreement', '[{"en":"The court made a landmark decision on privacy rights.","zh-TW":"法院就隱私權做出了里程碑式的裁決。"},{"en":"The tower is the city''s most famous landmark.","zh-TW":"這座塔是城市最著名的地標。"}]', '{"noun":"landmark"}', NULL, 3, 1216),
(1217, 'landscape', '/ˈlændskeɪp/', 'noun', '{"zh-TW":["風景；景觀","景觀；局勢"],"en":["the visible features of an area of land","the visible features of an area; the general situation"]}', '{"root":{"text":"land","meaning":"land (土地)"},"suffix":{"text":"scape","meaning":"view (景色)"},"logic":"土地的景色，即「風景」。"}', 'landscape painting / urban landscape; political/business landscape / landscape design', '[{"en":"The landscape in this region is breathtaking.","zh-TW":"這個地區的風景令人嘆為觀止。"},{"en":"She specializes in landscape photography.","zh-TW":"她專精風景攝影。"},{"en":"The business landscape has changed dramatically.","zh-TW":"商業格局發生了巨大的變化。"},{"en":"The landscape of the countryside is breathtaking.","zh-TW":"鄉村的景觀令人歎為觀止。"}]', '{"noun":"landscaping","verb":"landscape"}', NULL, 3, 1217),
(1218, 'language', '/ˈlæŋɡwɪdʒ/', 'noun', '{"zh-TW":["語言"],"en":["a system of communication"]}', NULL, 'body language / language barrier', '[{"en":"The language barrier made negotiations difficult.","zh-TW":"語言障礙使談判變得困難。"},{"en":"She speaks three languages fluently.","zh-TW":"她流利地說三種語言。"}]', '{"noun":"language","adjective":"linguistic","noun2":"linguistics"}', NULL, 3, 1218),
(1219, 'large', '/lɑːrdʒ/', 'adjective', '{"zh-TW":["大的；大規模的"],"en":["big in size or amount"]}', NULL, 'at large / by and large', '[{"en":"By and large, the plan was successful.","zh-TW":"總的來說，計畫是成功的。"},{"en":"We serve large corporate clients.","zh-TW":"我們服務大型企業客戶。"}]', '{"adjective":"large","adverb":"largely","verb":"enlarge","noun":"enlargement"}', NULL, 2, 1219),
(1220, 'last', '/lɑːst/', 'adjective', '{"zh-TW":["最後的；上一個；持續"],"en":["coming after all others","most recent","to continue"]}', NULL, 'at last / last resort', '[{"en":"As a last resort, we may outsource.","zh-TW":"作為最後手段，我們可能外包。"},{"en":"The meeting lasted two hours.","zh-TW":"會議持續了兩個小時。"}]', '{"adjective":"last","verb":"last","adverb":"lastly","adjective2":"lasting"}', NULL, 1, 1220),
(1221, 'late', '/leɪt/', 'adjective', '{"zh-TW":["遲的；晚的"],"en":["after the expected time","near the end"]}', NULL, 'too late / late fee', '[{"en":"A late fee will be charged after the due date.","zh-TW":"逾期將收取滯納金。"},{"en":"Sorry I am late for the meeting.","zh-TW":"抱歉我開會遲到了。"}]', '{"adjective":"late","adverb":"lately","adverb2":"late","noun":"lateness"}', NULL, 1, 1221),
(1222, 'latitude', '/ˈlætɪtjuːd/', 'noun', '{"zh-TW":["【主要意義】緯度","【次要意義】自由度；寬容度；行動或表達的自由空間"],"en":["[primary] the distance north or south of the equator","[secondary] freedom from restrictions; scope for action or thought"]}', NULL, 'give someone latitude / allow latitude / considerable latitude', '[{"en":"The manager gave her team considerable latitude in choosing their approach.","zh-TW":"經理給了她的團隊相當大的自由度來選擇他們的方法。"},{"en":"Journalists need latitude to investigate without interference.","zh-TW":"記者需要在不受干擾的情況下進行調查的自由度。"},{"en":"The new policy allows employees more latitude in their work schedules.","zh-TW":"新政策給予員工在工作時間安排上更多的靈活度。"}]', '{"adjective":"latitudinal"}', '除地理上的「緯度」外，latitude 在商業或管理語境中指「靈活度/自由裁量空間」，TOEIC 閱讀測驗中常見於描述管理或決策的文章。', 3, 1222),
(1223, 'laugh', '/læf/', 'verb', '{"zh-TW":["笑"],"en":["to make sounds showing amusement"]}', NULL, 'laugh at / have a laugh', '[{"en":"Don''t laugh at others'' mistakes.","zh-TW":"不要嘲笑別人的錯誤。"},{"en":"We had a good laugh at the team dinner.","zh-TW":"我們在團隊晚餐上笑得很開心。"}]', '{"verb":"laugh","noun":"laugh","noun2":"laughter"}', NULL, 2, 1223),
(1224, 'launch', '/lɔːntʃ/', 'verb', '{"zh-TW":["推出；發射","發射；推出；發起"],"en":["to start or introduce something new","to send into the air","to start or introduce something new; to send into the air"]}', '{"root":{"text":"launch","meaning":"throw (投擲)"},"logic":"源自古法語 lanchier（投擲），指推出新事物。"}', 'launch a product / launch a campaign / rocket launch; launch a product/campaign/website', '[{"en":"The company will launch a new product next week.","zh-TW":"公司下週將推出新產品。"},{"en":"NASA launched a satellite into orbit.","zh-TW":"NASA發射了一顆衛星進入軌道。"},{"en":"The company will launch its new product next month.","zh-TW":"公司將於下個月推出新產品。"},{"en":"They launched a marketing campaign on social media.","zh-TW":"他們在社群媒體上發起了行銷活動。"}]', '{"noun":"launch","verb":"launch"}', NULL, 2, 1224),
(1225, 'law', '/lɔː/', 'noun', '{"zh-TW":["法律；法規"],"en":["rules made by a government"]}', NULL, 'break/obey the law / by law / law firm', '[{"en":"It is against the law to discriminate based on gender.","zh-TW":"基於性別的歧視是違法的。"},{"en":"She works for a prestigious law firm.","zh-TW":"她在一家知名律師事務所工作。"}]', '{"noun":"law, lawyer, lawsuit","adjective":"lawful, legal"}', NULL, 1, 1225),
(1226, 'lawsuit', '/ˈlɔːsuːt/', 'noun', '{"zh-TW":["訴訟"],"en":["a legal case brought to court"]}', NULL, 'file a lawsuit / class-action lawsuit', '[{"en":"She filed a lawsuit against the company.","zh-TW":"她對公司提起了訴訟。"},{"en":"The lawsuit was settled out of court.","zh-TW":"訴訟在庭外和解了。"}]', NULL, NULL, 3, 1226),
(1227, 'layout', '/ˈleɪaʊt/', 'noun', '{"zh-TW":["佈局；版面設計"],"en":["the way things are arranged in a space"]}', NULL, 'office layout / page layout / floor layout', '[{"en":"The office layout was redesigned for better collaboration.","zh-TW":"辦公室佈局被重新設計以促進更好的合作。"},{"en":"She designed the layout of the new brochure.","zh-TW":"她設計了新宣傳冊的版面。"}]', '{"noun":"layout","verb":"lay out"}', NULL, 2, 1227),
(1228, 'lead', '/liːd/', 'verb, noun', '{"zh-TW":["領導；帶領","領先；主導地位"],"en":["to guide or direct; to be in charge","a position of advantage"]}', NULL, 'lead a team/project / take the lead', '[{"en":"She leads a team of ten engineers.","zh-TW":"她領導一個十人的工程師團隊。"},{"en":"Our company has taken the lead in innovation.","zh-TW":"我們公司在創新方面處於領先地位。"}]', '{"noun":"lead, leader, leadership","verb":"lead","adjective":"leading"}', NULL, 1, 1228),
